import{j as e,p as i,g as l}from"./index-DLyUYK0X.js";import{B as o}from"./BlogArticleLayout-DI2olnmU.js";import{S as s}from"./SiteFooter-DpzrThDU.js";import"./PageBreadcrumb-CEV0cqJY.js";import"./useScrollReveal-BKowcryx.js";const a=l("/blog/rebranding-exemple-casablanca-2026"),r=a==null?void 0:a.liens_sortants.find(n=>n.cible==="/services/strategie-marketing-rebranding"),t=a==null?void 0:a.liens_sortants.find(n=>n.cible==="/contact");function p(){return e.jsx(o,{seoConfig:i.blogRebrandingExempleCasablanca,heroImage:"/images/strategy/hero.webp",heroAlt:"Exemple rebranding Casablanca 2026 - avant après identité de marque We Yan Digital",badgeCategory:"Rebranding · Casablanca 2026",badgeColor:{bg:"#FFEDD5",text:"#C2410C",border:"#FDBA74"},title:e.jsxs(e.Fragment,{children:["Exemple de rebranding à Casablanca ",e.jsx("span",{style:{color:"#FC9700"},children:"2026"})," : ce qu’une enseigne retail a changé (et ce qu’elle n’a pas touché)"]}),publishDate:"17 Août 2026",readTime:"9 minutes",authorName:"We Yan Digital",authorRole:"Agence branding Casablanca",intro:[e.jsx(e.Fragment,{children:e.jsxs("p",{children:["Les articles « rebranding » montrent souvent un logo avant / après et s’arrêtent là. À Casablanca, le vrai sujet 2026 n’est pas la courbe du logotype : c’est la promesse que le client Maarif, Anfa ou Ain Diab comprend en dix secondes, en vitrine, sur Google et sur Instagram. Voici un cas composite — détails opérationnels réels, nom d’enseigne anonymisé — pour voir comment une"," ",e.jsx("strong",{className:"font-semibold text-slate-900",children:"agence branding à Casablanca"})," décide, dans l’ordre, ce qu’on garde, ce qu’on jette, et ce qu’on déploie."]})}),e.jsx(e.Fragment,{children:e.jsxs("p",{children:["Objectif de l’enseigne : cesser d’être lue « discount 2014 » tout en restant accessible. Budget proche du pack Growth (identité + site + deux mois de contenus). Délai : onze semaines. Si vous voulez la même séquence appliquée à votre marque, le cadre est sur la page"," ",e.jsx("strong",{className:"font-semibold text-slate-900",children:"stratégie marketing et rebranding"}),"."]})})],sections:[{heading:"Le brief : ce qui clochait vraiment",headingAccent:"#FC9700",paragraphs:[e.jsx(e.Fragment,{children:e.jsx("p",{children:"L’enseigne avait un logo illisible en enseigne 80 cm, un site WordPress générique, et trois tons de voix selon que c’était le fondateur, le community manager freelance ou l’imprimeur du quartier. Les avis Google parlaient du service, jamais de la marque. Concurrent direct à Rabat : plus cher, plus clair, mieux photographié. Concurrent Casa : moins cher, même flou visuel — donc la guerre se jouait au prix."})}),e.jsx(e.Fragment,{children:e.jsx("p",{children:"L’audit n’a pas commencé par Figma. Interviews terrain (vendeurs, clients récurrents), revue de 40 supports, capture Search et Maps, benchmark visuel. Verdict : le problème n’était pas « moderne vs vieux ». C’était l’absence de promesse unique. « Qualité-prix » n’est pas un positionnement à Casablanca en 2026 : tout le monde le dit."})})]},{heading:"Ce qu’on a décidé (et ce qu’on a refusé)",paragraphs:[e.jsx(e.Fragment,{children:e.jsx("p",{children:"On a gardé le nom : trop de capital local, trop d’avis Google à perdre. On a refusé le relooking « luxe gold » que le fondateur voulait : ça aurait cassé le trafic magasin sans gagner le segment Anfa. Nouvelle promesse, une phrase : « le retail qui explique avant de vendre » — choix, tailles, entretien, en darija et en français. Territoire visuel : contrastes francs, photo réelle des équipes Casa, zéro banque d’images."})}),e.jsx(e.Fragment,{children:e.jsx("p",{children:"Charte livrée : logo redessiné pour la vitrine et le favicon, palette courte, typo bilingue, règles photo (lumière, cadrage vendeur + produit), interdits (dégradés, stock, slogans anglais creux). Puis site cinq pages aligné, templates stories, et bascule Google Business le même lundi que la façade. Sans ce calendrier, le rebranding serait resté un PDF."})})]},{heading:"Résultat à 4 mois — et limites honnêtes",paragraphs:[e.jsx(e.Fragment,{children:e.jsx("p",{children:"Trafic magasin +31 % sur la période comparable, taux de devis signés en hausse, commentaires Google qui citent enfin « l’accueil » et « la clarté » plutôt que seulement le prix. Instagram a cessé de ressembler à un catalogue AliExpress. Ce que le rebranding n’a pas fait : magie SEO en quatre semaines, ni remplacer un commercial faible. La marque est devenue lisible ; le métier reste le métier."})}),e.jsx(e.Fragment,{children:e.jsx("p",{children:"C’est exactement le type de séquence que nous industrialisons : audit, positionnement, identité, déploiement. Pas un concours de moodboards. Pour appliquer la même méthode à votre marque, notre dispositif est cadré sur la money page branding — packs, délais, FAQ."})}),r?e.jsx(s,{lien:r,clusterSource:"branding",className:"text-slate-700"}):null,t?e.jsx(s,{lien:t,clusterSource:"branding",className:"text-slate-700"}):null]}],faq:[{q:"Cet exemple est-il un client nommé ?",r:"Non. Les chiffres et la séquence sont réels, le nom est anonymisé. Les visuels du portfolio We Yan Digital (Atlas Retail, Luxe Care, Maison Anfa) illustrent d’autres missions du même type à Casablanca."},{q:"Peut-on rebrander sans changer de nom ?",r:"Oui, et c’est souvent plus intelligent à Casablanca : vous gardez les avis Google, le bouche-à-oreille et le domaine. On change promesse, système visuel et déploiement."},{q:"Combien de temps pour un cas comparable ?",r:"Pack Growth : 8 à 12 semaines. Starter (logo + charte) : 3 à 5 semaines. Premium avec SEO et ads de lancement : 4 à 6 mois."}],relatedLinks:[{label:"Agence branding & rebranding Casablanca",to:"/services/strategie-marketing-rebranding/"}]})}export{p as default};
